 @Test void tamabbohBInitRetainsPositionPrefixBeforeTheGenuineAngleFault()throws Exception{
  for(int damaged:new int[]{0,2})for(int secondary:new int[]{0,1}){var f=fixture();selected(f,0x22,damaged,secondary);var fault=new IllegalStateException("native floor angle");var body=tam(f,c->{throw fault;},c->{fail("no Fire FM");},(p,id)->fail("no Draw yet"),noGuard());assertSame(fault,assertThrows(IllegalStateException.class,()->body.run(32,new CdTamabboh.Globals(0,0,0,0,0x300,0x5A))));var s=f.placement().pool().state(32);assertEquals(2,s.routine());assertEquals(0x235,s.centreY());assertEquals(secondary==0?0x2403:0x4334,s.word(TILE));assertEquals(CdR11bObjectData.Table.MAP_SPR_TAMABBOH1.nativeAddress()+(damaged==0?0:22),s.longBits(MAPPINGS));assertEquals(damaged==0?-0xA000:-0x5000,s.longBits(TAMABBOH_X_DELTA));assertEquals(0x2C,s.unsignedByte(COLLISION_TYPE));assertEquals(0,fault.getSuppressed().length);}
 }
 @Test void tamabbohFireAllocatesTwoActualID22Subtype1ChildrenBeforeFreshFind()throws Exception{
  var f=fixture();var s=selected(f,0x22,0,0).moveByte(ROUTINE,10).moveWord(TILE,0x2403).moveByte(PRIORITY,4).moveWord(TAMABBOH_ANCHOR_X,0x345);f.placement().pool().write(s);var finds=new AtomicInteger();var obs=new CdEnemyPrimitiveScope.Observer(){public void before(CdEnemyPrimitiveScope.Call c){if(c.kind()==CdEnemyPrimitiveScope.Kind.FIND)finds.incrementAndGet();}public void after(CdEnemyPrimitiveScope.Call c){}};var body=tam(f,c->{fail("Fire does not read floor");},c->{fail("old nonnegative flags skip FM");},(p,id)->{},obs);body.run(32,new CdTamabboh.Globals(0,0,0,0,0x300,0));assertEquals(2,finds.get());for(int w:new int[]{33,34}){var child=f.placement().pool().state(w);assertEquals(0x22,child.id());assertEquals(1,child.subtype());assertEquals(0x2403,child.word(TILE));assertEquals(5,child.unsignedByte(PRIORITY));assertEquals(0x345,child.centreX());assertEquals(0x22A,child.centreY());assertEquals(w==33?0:255,child.unsignedByte(TAMABBOH_MISSILE_DIRECTION));assertEquals(0,child.routine());}assertEquals(4,f.placement().pool().state(32).routine());assertEquals(0x78,f.placement().pool().state(32).word(TAMABBOH_COOLDOWN));
 }
 @Test void subtypeOneChildDispatchPrecedesParentGlobalsAndUsesBMissileRoot()throws Exception{
  var f=fixture();selected(f,0x22,1,0);var body=tam(f,c->{fail("no child Init floor");},c->{fail("no child Init FM");},(p,id)->{},noGuard());var unread=new CdTamabboh.Reads(){private int wrong(){throw new AssertionError("unreached parent read");}public int goodFuture(){return wrong();}public int timeZone(){return wrong();}public int timeWarpDirection(){return wrong();}public int debugMode(){return wrong();}public int cameraXWord(){return wrong();}public int primaryAngle(){return 0x45;}};body.run(32,unread);var s=f.placement().pool().state(32);assertEquals(2,s.routine());assertEquals(0xAD,s.unsignedByte(COLLISION_TYPE));assertEquals(CdR11bObjectData.Table.MAP_SPR_TAMABBOH_MISSILE.nativeAddress(),s.longBits(MAPPINGS));assertEquals(0x20000,s.longBits(TAMABBOH_MISSILE_X_DELTA));assertEquals(-0x40000,s.longBits(TAMABBOH_MISSILE_Y_DELTA));assertEquals(0x345,s.centreX());assertEquals(0x234,s.centreY());
 }
 @Test void fullPlacementRestoreReplaysTamabbohChildGraphWithFreshPrivateReceipts()throws Exception{
  var f=fixture();var s=selected(f,0x22,0,0).moveByte(ROUTINE,10).moveWord(TILE,0x2403).moveWord(TAMABBOH_ANCHOR_X,0x345);f.placement().pool().write(s);var before=f.placement().capture();var last=new AtomicReference<CdEnemyPrimitiveScope.Call>();var body=tam(f,c->{},c->{},(p,id)->{},new CdEnemyPrimitiveScope.Observer(){public void before(CdEnemyPrimitiveScope.Call c){last.set(c);}public void after(CdEnemyPrimitiveScope.Call c){}});body.run(32,new CdTamabboh.Globals(0,0,0,0,0x300,0));var expected=f.placement().capture();var stale=last.get();assertFalse(body.isCurrentOriginalPrimitive(stale));f.placement().restore(before);body.run(32,new CdTamabboh.Globals(0,0,0,0,0x300,0));same(expected,f.placement().capture());assertTrue(last.get().generation()>stale.generation());assertFalse(body.isCurrentOriginalPrimitive(stale));
 }
